CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE module_code AS ENUM ('capital.wallets','capital.testnet_funding','capital.lending','trade.spot','trade.stocks','trade.perps','trade.commodities');
CREATE TABLE businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, environment text NOT NULL DEFAULT 'stellar-testnet' CHECK(environment='stellar-testnet'), revision integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE business_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, auth_provider_id text NOT NULL, role text NOT NULL CHECK(role='owner'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,auth_provider_id));
CREATE TABLE owner_sessions (token_hash text PRIMARY KEY, business_id uuid NOT NULL REFERENCES businesses, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE business_modules (business_id uuid NOT NULL REFERENCES businesses, module_code module_code NOT NULL, enabled boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(business_id,module_code));
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, prefix text NOT NULL, last_four text NOT NULL, key_hash text NOT NULL UNIQUE, name text NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, UNIQUE(business_id,id));
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, external_customer_id text NOT NULL, privy_user_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,external_customer_id), UNIQUE(business_id,id));
CREATE TABLE wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, customer_id uuid NOT NULL, privy_wallet_id text NOT NULL, stellar_address text NOT NULL, public_key text NOT NULL, network text NOT NULL DEFAULT 'stellar-testnet' CHECK(network='stellar-testnet'), status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id), UNIQUE(business_id,customer_id,network), UNIQUE(business_id,customer_id,id), UNIQUE(business_id,id));
CREATE TABLE assets (id text PRIMARY KEY, network text NOT NULL CHECK(network='stellar-testnet'), kind text NOT NULL CHECK(kind IN ('native','classic','soroban')), code text NOT NULL, issuer text, contract_id text, decimals integer NOT NULL CHECK(decimals BETWEEN 0 AND 38), verified boolean NOT NULL DEFAULT false, source_url text NOT NULL, verified_at timestamptz, demo_only boolean NOT NULL DEFAULT true, UNIQUE NULLS NOT DISTINCT(network,kind,code,issuer,contract_id));
CREATE TABLE provider_markets (id text PRIMARY KEY, module_code module_code NOT NULL, provider text NOT NULL, contract_id text, asset_in_id text REFERENCES assets, asset_out_id text REFERENCES assets, network text NOT NULL CHECK(network='stellar-testnet'), readiness text NOT NULL DEFAULT 'discovery_only', reason text, as_of timestamptz);
CREATE TABLE operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, customer_id uuid NOT NULL, wallet_id uuid NOT NULL, module_code module_code NOT NULL, type text NOT NULL, state text NOT NULL CHECK(state IN ('accepted','validating','preparing','awaiting_customer_authorization','submitted','confirming','completed','rejected','expired','failed','recovery_required')), network text NOT NULL DEFAULT 'stellar-testnet' CHECK(network='stellar-testnet'), request_json jsonb NOT NULL, approved_intent_hash text, xdr_hash text, prepared_action jsonb, signed_xdr text, tx_hash text, provider text NOT NULL, provider_ref text, error_code text, error_message text, result_json jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_checked_at timestamptz, FOREIGN KEY(business_id,customer_id,wallet_id) REFERENCES wallets(business_id,customer_id,id), UNIQUE(business_id,id), UNIQUE(business_id,customer_id,wallet_id,id), CHECK(state <> 'completed' OR tx_hash IS NOT NULL));
CREATE UNIQUE INDEX operations_tx_hash ON operations(network,tx_hash) WHERE tx_hash IS NOT NULL;
CREATE TABLE wallet_authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, customer_id uuid NOT NULL, wallet_id uuid NOT NULL, operation_id uuid NOT NULL, intent_hash text NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, consumed_at timestamptz, status text NOT NULL DEFAULT 'pending', FOREIGN KEY(business_id,customer_id,wallet_id,operation_id) REFERENCES operations(business_id,customer_id,wallet_id,id));
CREATE TABLE operation_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL, business_id uuid NOT NULL, attempt_no integer NOT NULL, provider text NOT NULL, tx_hash text, response_json_redacted jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,operation_id) REFERENCES operations(business_id,id), UNIQUE(operation_id,attempt_no));
CREATE TABLE idempotency_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, route text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, operation_id uuid NOT NULL, FOREIGN KEY(business_id,operation_id) REFERENCES operations(business_id,id), UNIQUE(business_id,route,idempotency_key));
CREATE TABLE balance_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, customer_id uuid NOT NULL, wallet_id uuid NOT NULL, asset_id text NOT NULL REFERENCES assets, operation_id uuid NOT NULL, amount_atomic numeric(78,0) NOT NULL CHECK(amount_atomic>0), state text NOT NULL DEFAULT 'active', expires_at timestamptz NOT NULL, FOREIGN KEY(business_id,customer_id,wallet_id,operation_id) REFERENCES operations(business_id,customer_id,wallet_id,id));
CREATE TABLE testnet_funding_transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, customer_id uuid NOT NULL, wallet_id uuid NOT NULL, operation_id uuid NOT NULL UNIQUE, direction text NOT NULL CHECK(direction IN ('fund','return')), asset_id text NOT NULL REFERENCES assets, amount_atomic numeric(78,0) NOT NULL CHECK(amount_atomic>0), treasury_address text NOT NULL, tx_hash text, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,customer_id,wallet_id,operation_id) REFERENCES operations(business_id,customer_id,wallet_id,id));
CREATE TABLE trade_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, customer_id uuid NOT NULL, market_id text NOT NULL REFERENCES provider_markets, provider text NOT NULL, exact_in_asset_id text NOT NULL REFERENCES assets, amount_in_atomic numeric(78,0) NOT NULL CHECK(amount_in_atomic>0), expected_out_atomic numeric(78,0) NOT NULL, min_out_atomic numeric(78,0) NOT NULL, expires_at timestamptz NOT NULL, provider_quote_json_redacted jsonb, FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id), UNIQUE(business_id,customer_id,id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, customer_id uuid NOT NULL, operation_id uuid NOT NULL, quote_id uuid NOT NULL, market_id text NOT NULL REFERENCES provider_markets, status text NOT NULL, actual_in_atomic numeric(78,0), actual_out_atomic numeric(78,0), tx_hash text, FOREIGN KEY(business_id,operation_id) REFERENCES operations(business_id,id), FOREIGN KEY(business_id,customer_id,quote_id) REFERENCES trade_quotes(business_id,customer_id,id), UNIQUE(business_id,id));
CREATE TABLE lending_positions_cache (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL, customer_id uuid NOT NULL, wallet_id uuid NOT NULL, pool_contract_id text NOT NULL, reserve_contract_id text NOT NULL, supplied_atomic numeric(78,0), debt_atomic numeric(78,0), as_of timestamptz NOT NULL, ledger bigint, FOREIGN KEY(business_id,customer_id,wallet_id) REFERENCES wallets(business_id,customer_id,id));
CREATE TABLE api_request_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, api_key_id uuid, request_id text NOT NULL, method text NOT NULL, path_template text NOT NULL, status integer NOT NULL, duration_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(business_id,api_key_id) REFERENCES api_keys(business_id,id));
CREATE TABLE worker_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES operations, job_type text NOT NULL, state text NOT NULL DEFAULT 'pending', lease_until timestamptz, lease_owner text, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), UNIQUE(operation_id,job_type));
